// Pass 1: per-channel Welford reduction, one CTA per channel.
// grid = (C,), block = (256,)
// ---------------------------------------------------------------------------
__global__ void bn_stats_kernel_welford(
    const float* __restrict__ x,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    int N, int C)
{
    int c = blockIdx.x;          // one block per channel
    int tid = threadIdx.x;
    int block_size = blockDim.x; // 256

    // Per-thread Welford accumulators
    float t_mean = 0.f, t_M2 = 0.f;
    int   t_cnt  = 0;

    // Each thread strides over the N rows
    for (int n = tid; n < N; n += block_size) {
        float v = x[(long)n * C + c];
        t_cnt  += 1;
        float delta = v - t_mean;
        t_mean += delta / (float)t_cnt;
        t_M2   += delta * (v - t_mean);
    }

    // -----------------------------------------------------------------------
    // Warp-level Welford combine via shuffle
    // -----------------------------------------------------------------------
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset >= 1; offset >>= 1) {
        float o_mean = __shfl_down_sync(mask, t_mean, offset);
        float o_M2   = __shfl_down_sync(mask, t_M2,   offset);
        int   o_cnt  = __shfl_down_sync(mask, t_cnt,  offset);
        // Parallel Welford combine
        int combined = t_cnt + o_cnt;
        if (combined > 0) {
            float delta2 = o_mean - t_mean;
            t_mean = (t_mean * t_cnt + o_mean * o_cnt) / (float)combined;
            t_M2   = t_M2 + o_M2 + delta2 * delta2 * ((float)t_cnt * (float)o_cnt / (float)combined);
            t_cnt  = combined;
        }
    }

    // One partial accumulator per warp written to shared memory
    // max 8 warps for 256 threads
    __shared__ float s_mean[8];
    __shared__ float s_M2  [8];
    __shared__ int   s_cnt [8];

    int lane  = tid & 31;
    int warpid = tid >> 5;
    int nwarps = (block_size + 31) >> 5;

    if (lane == 0) {
        s_mean[warpid] = t_mean;
        s_M2  [warpid] = t_M2;
        s_cnt [warpid] = t_cnt;
    }
    __syncthreads();

    // Final combine by warp 0
    if (warpid == 0) {
        float f_mean = (lane < nwarps) ? s_mean[lane] : 0.f;
        float f_M2   = (lane < nwarps) ? s_M2  [lane] : 0.f;
        int   f_cnt  = (lane < nwarps) ? s_cnt [lane] : 0;

