#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// ---------------------------------------------------------------------------
// Pass 1: per-channel Welford reduction, one CTA per channel.
// grid = (C,), block = (256,)
// ---------------------------------------------------------------------------
__global__ void bn_stats_kernel_welford(
    const float* __restrict__ x,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    int N, int C)
{
    int c = blockIdx.x;          // one block per channel
    int tid = threadIdx.x;
    int block_size = blockDim.x; // 256

    // Per-thread Welford accumulators
    float t_mean = 0.f, t_M2 = 0.f;
    int   t_cnt  = 0;

    // Each thread strides over the N rows
    for (int n = tid; n < N; n += block_size) {
        float v = x[(long)n * C + c];
        t_cnt  += 1;
        float delta = v - t_mean;
        t_mean += delta / (float)t_cnt;
        t_M2   += delta * (v - t_mean);
    }

    // -----------------------------------------------------------------------
    // Warp-level Welford combine via shuffle
    // -----------------------------------------------------------------------
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset >= 1; offset >>= 1) {
        float o_mean = __shfl_down_sync(mask, t_mean, offset);
        float o_M2   = __shfl_down_sync(mask, t_M2,   offset);
        int   o_cnt  = __shfl_down_sync(mask, t_cnt,  offset);
        // Parallel Welford combine
        int combined = t_cnt + o_cnt;
        if (combined > 0) {
            float delta2 = o_mean - t_mean;
            t_mean = (t_mean * t_cnt + o_mean * o_cnt) / (float)combined;
            t_M2   = t_M2 + o_M2 + delta2 * delta2 * ((float)t_cnt * (float)o_cnt / (float)combined);
            t_cnt  = combined;
        }
    }

    // One partial accumulator per warp written to shared memory
    // max 8 warps for 256 threads
    __shared__ float s_mean[8];
    __shared__ float s_M2  [8];
    __shared__ int   s_cnt [8];

    int lane  = tid & 31;
    int warpid = tid >> 5;
    int nwarps = (block_size + 31) >> 5;

    if (lane == 0) {
        s_mean[warpid] = t_mean;
        s_M2  [warpid] = t_M2;
        s_cnt [warpid] = t_cnt;
    }
    __syncthreads();

    // Final combine by warp 0
    if (warpid == 0) {
        float f_mean = (lane < nwarps) ? s_mean[lane] : 0.f;
        float f_M2   = (lane < nwarps) ? s_M2  [lane] : 0.f;
        int   f_cnt  = (lane < nwarps) ? s_cnt [lane] : 0;

        #pragma unroll
        for (int offset = 4; offset >= 1; offset >>= 1) {
            float o_mean = __shfl_down_sync(mask, f_mean, offset);
            float o_M2   = __shfl_down_sync(mask, f_M2,   offset);
            int   o_cnt  = __shfl_down_sync(mask, f_cnt,  offset);
            int combined = f_cnt + o_cnt;
            if (combined > 0) {
                float delta2 = o_mean - f_mean;
                f_mean = (f_mean * f_cnt + o_mean * o_cnt) / (float)combined;
                f_M2   = f_M2 + o_M2 + delta2 * delta2 * ((float)f_cnt * (float)o_cnt / (float)combined);
                f_cnt  = combined;
            }
        }

        if (lane == 0) {
            mean_out[c] = f_mean;
            var_out [c] = (f_cnt > 0) ? (f_M2 / (float)f_cnt) : 0.f;
        }
    }
}

// ---------------------------------------------------------------------------
// Pass 2 scalar: normalize + affine + extra_bias + divide + swish
// bias_numel: 1 (broadcast) or C (channel-wise)
// ---------------------------------------------------------------------------
__global__ void bn_apply_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const float* __restrict__ mean,
    const float* __restrict__ inv_std,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ extra_bias,
    int N, int C,
    int bias_numel,
    float divide_value)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C;
    if (idx >= total) return;

    int c = idx % C;
    float v = x[idx];
    float norm = (v - mean[c]) * inv_std[c];
    float y = norm * weight[c] + bias[c];
    float eb = (bias_numel == 1) ? extra_bias[0] : extra_bias[c];
    y = (y + eb) / divide_value;
    y = y * (1.f / (1.f + __expf(-y)));
    out[idx] = y;
}

// ---------------------------------------------------------------------------
// Pass 2 vectorized: float4 path when C % 4 == 0 and pointers are 16-byte aligned.
// Each thread handles 4 consecutive channel elements for a fixed row.
// Layout [N, C]: thread idx maps to (n, c_base) where c_base = (idx % (C/4)) * 4.
// bias_is_scalar: compile-time-like bool passed as int
// ---------------------------------------------------------------------------
__global__ void bn_apply_kernel_vec4(
    const float4* __restrict__ x4,
    float4* __restrict__ out4,
    const float* __restrict__ mean,
    const float* __restrict__ inv_std,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ extra_bias,
    int N, int C,
    int bias_numel,
    float divide_value)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total4 = N * (C / 4);
    if (idx >= total4) return;

    int c4 = idx % (C / 4);  // which group of 4 channels
    int c_base = c4 * 4;

    float4 xv = __ldg(x4 + idx);

    // Load 4 mean / inv_std / weight / bias values
    float m0 = __ldg(mean    + c_base),     m1 = __ldg(mean    + c_base + 1),
          m2 = __ldg(mean    + c_base + 2), m3 = __ldg(mean    + c_base + 3);
    float s0 = __ldg(inv_std + c_base),     s1 = __ldg(inv_std + c_base + 1),
          s2 = __ldg(inv_std + c_base + 2), s3 = __ldg(inv_std + c_base + 3);
    float w0 = __ldg(weight  + c_base),     w1 = __ldg(weight  + c_base + 1),
          w2 = __ldg(weight  + c_base + 2), w3 = __ldg(weight  + c_base + 3);
    float b0 = __ldg(bias    + c_base),     b1 = __ldg(bias    + c_base + 1),
          b2 = __ldg(bias    + c_base + 2), b3 = __ldg(bias    + c_base + 3);

    float eb0, eb1, eb2, eb3;
    if (bias_numel == 1) {
        eb0 = eb1 = eb2 = eb3 = __ldg(extra_bias);
    } else {
        eb0 = __ldg(extra_bias + c_base);
        eb1 = __ldg(extra_bias + c_base + 1);
        eb2 = __ldg(extra_bias + c_base + 2);
        eb3 = __ldg(extra_bias + c_base + 3);
    }

    float inv_dv = 1.f / divide_value;

    auto swish = [](float v) -> float {
        return v * (1.f / (1.f + __expf(-v)));
    };

    float y0 = swish(((xv.x - m0) * s0 * w0 + b0 + eb0) * inv_dv);
    float y1 = swish(((xv.y - m1) * s1 * w1 + b1 + eb1) * inv_dv);
    float y2 = swish(((xv.z - m2) * s2 * w2 + b2 + eb2) * inv_dv);
    float y3 = swish(((xv.w - m3) * s3 * w3 + b3 + eb3) * inv_dv);

    out4[idx] = make_float4(y0, y1, y2, y3);
}

torch::Tensor matmul_batchnorm_biasadd_divide_swish_cuda(
    torch::Tensor x,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor extra_bias,
