__global__ void bn_stats_kernel(
    const float* __restrict__ x,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    int N, int C)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;

    float sum = 0.f;
    float sum_sq = 0.f;
    for (int n = 0; n < N; n++) {
        float v = x[(long)n * C + c];
        sum    += v;
        sum_sq += v * v;
    }
    float mean = sum / N;
    float var  = sum_sq / N - mean * mean;
    mean_out[c] = mean;
    var_out[c]  = var > 0.f ? var : 0.f;
}

__global__ void bn_apply_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const float* __restrict__ mean,
    const float* __restrict__ inv_std,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ extra_bias,
    int N, int C,
    int bias_numel,
    float divide_value)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C;
    if (idx >= total) return;

    int c = idx % C;
    float v = x[idx];
    float norm = (v - mean[c]) * inv_std[c];
    float y = norm * weight[c] + bias[c];
    float eb = (bias_numel == 1) ? extra_bias[0] : extra_bias[c];
    y = (y + eb) / divide_value;
    y = y * (1.f / (1.f + __expf(-y)));
    out[idx] = y;
}

