__global__ void bn_stats_kernel(
    const float* __restrict__ x,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    int N, int C)
{
    int c = blockIdx.x;
    int tid = threadIdx.x;
    __shared__ float s_sum[256];
    __shared__ float s_sumsq[256];

    float sum = 0.f;
    float sumsq = 0.f;
    for (int n = tid; n < N; n += blockDim.x) {
        float v = x[(long)n * C + c];
        sum += v;
        sumsq += v * v;
    }

    s_sum[tid] = sum;
    s_sumsq[tid] = sumsq;
    __syncthreads();

    for (int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid + stride];
            s_sumsq[tid] += s_sumsq[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = s_sum[0] / (float)N;
        float var = s_sumsq[0] / (float)N - mean * mean;
        mean_out[c] = mean;
        var_out[c] = var > 0.f ? var : 0.f;
    }
}

__global__ void bn_apply_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const float* __restrict__ mean,
    const float* __restrict__ inv_std,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int bias_numel,
    const float* __restrict__ extra_bias,
    int extra_bias_numel,
    int N, int C,
    float divide_value)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C;
    if (idx >= total) return;

    int c = idx % C;
    float b = (bias_numel == 1) ? bias[0] : bias[c];
    float eb = (extra_bias_numel == 1) ? extra_bias[0] : extra_bias[c];
    float y = (x[idx] - mean[c]) * inv_std[c];
    y = (y * weight[c] + b + eb) / divide_value;
    out[idx] = y * (1.f / (1.f + __expf(-y)));
}

__global__ void bn_apply_kernel_vec4(
    const float4* __restrict__ x4,
    float4* __restrict__ out4,
    const float* __restrict__ mean,
    const float* __restrict__ inv_std,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int bias_numel,
    const float* __restrict__ extra_bias,
    int extra_bias_numel,
    int N, int C,
    float divide_value)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total4 = N * (C / 4);
    if (idx >= total4) return;

    int c_base = (idx % (C / 4)) * 4;
    int c0 = c_base, c1 = c_base + 1, c2 = c_base + 2, c3 = c_base + 3;

    float4 xv = x4[idx];
    float b0 = (bias_numel == 1) ? bias[0] : bias[c0];
    float b1 = (bias_numel == 1) ? bias[0] : bias[c1];
    float b2 = (bias_numel == 1) ? bias[0] : bias[c2];
    float b3 = (bias_numel == 1) ? bias[0] : bias[c3];
    float eb0 = (extra_bias_numel == 1) ? extra_bias[0] : extra_bias[c0];
    float eb1 = (extra_bias_numel == 1) ? extra_bias[0] : extra_bias[c1];
    float eb2 = (extra_bias_numel == 1) ? extra_bias[0] : extra_bias[c2];
    float eb3 = (extra_bias_numel == 1) ? extra_bias[0] : extra_bias[c3];

    float y0 = ((xv.x - mean[c0]) * inv_std[c0] * weight[c0] + b0 + eb0) / divide_value;
    float y1 = ((xv.y - mean[c1]) * inv_std[c1] * weight[c1] + b1 + eb1) / divide_value;
    float y2 = ((xv.z - mean[c2]) * inv_std[c2] * weight[c2] + b2 + eb2) / divide_value;
    float y3 = ((xv.w - mean[c3]) * inv_std[c3] * weight[c3] + b3 + eb3) / divide_value;

    out4[idx] = make_float4(
        y0 * (1.f / (1.f + __expf(-y0))),
        y1 * (1.f / (1.f + __expf(-y1))),
        y2 * (1.f / (1.f + __expf(-y2))),
        y3 * (1.f / (1.f + __expf(-y3))));
}

// Eval-only kernel: out = swish(x * eff_scale + eff_bias) with float4 vectorization
__global__ void __launch_bounds__(256, 4) eval_affine_swish_vec4(
    const float4* __restrict__ x4,
    float4* __restrict__ out4,
    const float4* __restrict__ eff_scale4,
    const float4* __restrict__ eff_bias4,
    int total4)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total4) return;

    int c4 = idx % (gridDim.y > 0 ? gridDim.y : 1);  // unused, use c-based indexing
    float4 xv = x4[idx];
    // eff_scale4 and eff_bias4 are indexed by channel-group: idx % (C/4)
    // We pass total4 = N*(C/4), c4_idx = idx % (C/4) from caller side
    // But we don't have C here â we rely on the fact that eff_scale4/eff_bias4
    // have length C/4 and we stride correctly via a second parameter
    // Actually store c4_idx in a separate param or encode differently.
    // Simplest: pass C/4 as a param.
    // This kernel variant uses gridDim.y to store C/4.
    int c4_idx = idx % gridDim.y;
    float4 sv = __ldg(eff_scale4 + c4_idx);
    float4 bv = __ldg(eff_bias4 + c4_idx);

    float y0 = xv.x * sv.x + bv.x;
    float y1 = xv.y * sv.y + bv.y;
    float y2 = xv.z * sv.z + bv.z;
    float y3 = xv.w * sv.w + bv.w;

    out4[idx] = make_float4(
        y0 * (1.f / (1.f + __expf(-y0))),
        y1 * (1.f / (1.f + __expf(-y1))),
        y2 * (1.f / (1.f + __expf(-y2))),
        y3 * (1.f / (1.f + __expf(-y3))));
}

__global__ void __launch_bounds__(256, 4) eval_affine_swish_scalar(
    const float* __restrict__ x,
    float* __restrict__ out,
    const float* __restrict__ eff_scale,
    const float* __restrict__ eff_bias,
    int N, int C)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * C) return;
    int c = idx % C;
    float y = x[idx] * __ldg(eff_scale + c) + __ldg(eff_bias + c);
    out[idx] = y * (1.f / (1.f + __expf(-y)));
}

torch::Tensor matmul_batchnorm_biasadd_divide_swish_cuda(
    torch::Tensor x,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
